"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

export interface CommandItem {
  id: string;
  label: string;
  group: string;
  keywords?: string;
}

export function CommandPalette({
  open,
  onOpenChange,
  items,
  onSelect,
  placeholder = "Search...",
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  items: CommandItem[];
  onSelect: (item: CommandItem) => void;
  placeholder?: string;
}) {
  const [query, setQuery] = useState("");
  const [highlighted, setHighlighted] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const shouldReduceMotion = useReducedMotion();

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return items;
    return items.filter(
      (item) =>
        item.label.toLowerCase().includes(q) ||
        item.group.toLowerCase().includes(q) ||
        item.keywords?.toLowerCase().includes(q)
    );
  }, [items, query]);

  const groups = useMemo(() => {
    const map = new Map<string, CommandItem[]>();
    filtered.forEach((item) => {
      if (!map.has(item.group)) map.set(item.group, []);
      map.get(item.group)?.push(item);
    });
    return Array.from(map.entries());
  }, [filtered]);

  const [prevOpen, setPrevOpen] = useState(open);
  if (open !== prevOpen) {
    setPrevOpen(open);
    if (open) {
      setQuery("");
      setHighlighted(0);
    }
  }

  useEffect(() => {
    if (open) requestAnimationFrame(() => inputRef.current?.focus());
  }, [open]);

  const handleQueryChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setQuery(e.target.value);
    setHighlighted(0);
  };

  // also listen globally for cmd/ctrl+K to toggle open from anywhere on the page
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        onOpenChange(!open);
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [open, onOpenChange]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setHighlighted((h) => Math.min(h + 1, filtered.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setHighlighted((h) => Math.max(h - 1, 0));
    } else if (e.key === "Enter") {
      e.preventDefault();
      const item = filtered[highlighted];
      if (item) {
        onSelect(item);
        onOpenChange(false);
      }
    } else if (e.key === "Escape") {
      e.preventDefault();
      onOpenChange(false);
    }
  };

  const activeItem = filtered[highlighted];

  return (
    <AnimatePresence>
      {open && (
        <>
          <motion.div
            key="backdrop"
            aria-hidden
            className="fixed inset-0 z-50 bg-slate-950/40 backdrop-blur-sm"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: shouldReduceMotion ? 0.1 : 0.2 }}
            onClick={() => onOpenChange(false)}
          />
          <motion.div
            key="dialog"
            role="dialog"
            aria-modal="true"
            aria-label="Command palette"
            className="fixed left-1/2 top-24 z-50 w-[calc(100%-2rem)] max-w-lg"
            initial={shouldReduceMotion ? { opacity: 0, x: "-50%" } : { opacity: 0, scale: 0.96, y: -8, x: "-50%" }}
            animate={{ opacity: 1, scale: 1, y: 0, x: "-50%" }}
            exit={shouldReduceMotion ? { opacity: 0, x: "-50%" } : { opacity: 0, scale: 0.98, y: -6, x: "-50%" }}
            transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
          >
            <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl dark:border-slate-700 dark:bg-neutral-950">
              <div className="flex items-center gap-2.5 border-b border-slate-200 px-4 dark:border-slate-700">
                <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden className="shrink-0 text-slate-400 dark:text-slate-500">
                  <circle cx="11" cy="11" r="7" />
                  <line x1="21" y1="21" x2="16.65" y2="16.65" />
                </svg>
                <input
                  ref={inputRef}
                  role="combobox"
                  aria-expanded="true"
                  aria-controls="cmdk-listbox"
                  aria-activedescendant={activeItem ? `cmdk-option-${activeItem.id}` : undefined}
                  aria-autocomplete="list"
                  value={query}
                  onChange={handleQueryChange}
                  onKeyDown={handleKeyDown}
                  placeholder={placeholder}
                  className="w-full bg-transparent py-3.5 text-sm text-slate-900 outline-none placeholder:text-slate-400 dark:text-white"
                />
                <kbd className="hidden shrink-0 rounded border border-slate-200 px-1.5 py-0.5 text-[10px] font-medium text-slate-400 sm:inline-block dark:border-slate-700 dark:text-slate-500">
                  esc
                </kbd>
              </div>

              <div id="cmdk-listbox" role="listbox" className="max-h-80 overflow-y-auto p-2">
                {groups.length === 0 && (
                  <p className="px-3 py-6 text-center text-sm text-slate-400 dark:text-slate-500">
                    No results for "{query}"
                  </p>
                )}
                {groups.map(([group, groupItems]) => (
                  <div key={group} className="mb-1 last:mb-0">
                    <p className="px-3 pb-1 pt-2 text-[10px] font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">
                      {group}
                    </p>
                    {groupItems.map((item) => {
                      const index = filtered.indexOf(item);
                      const isHighlighted = index === highlighted;
                      return (
                        <div
                          key={item.id}
                          id={`cmdk-option-${item.id}`}
                          role="option"
                          aria-selected={isHighlighted}
                          onMouseEnter={() => setHighlighted(index)}
                          onClick={() => {
                            onSelect(item);
                            onOpenChange(false);
                          }}
                          className="relative cursor-pointer rounded-lg px-3 py-2 text-sm"
                        >
                          {isHighlighted && (
                            <motion.span
                              layoutId="cmdk-highlight"
                              className="absolute inset-0 rounded-lg bg-emerald-50 dark:bg-emerald-500/10"
                              transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 600, damping: 40 }}
                            />
                          )}
                          <span className={`relative ${isHighlighted ? "text-emerald-700 dark:text-emerald-400" : "text-slate-700 dark:text-slate-300"}`}>
                            {item.label}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                ))}
              </div>

              <div className="flex items-center gap-3 border-t border-slate-200 px-4 py-2 dark:border-slate-700">
                <span className="inline-flex items-center gap-1 text-[11px] text-slate-400 dark:text-slate-500">
                  <kbd className="rounded border border-slate-200 px-1 py-px dark:border-slate-700">↑↓</kbd>
                  navigate
                </span>
                <span className="inline-flex items-center gap-1 text-[11px] text-slate-400 dark:text-slate-500">
                  <kbd className="rounded border border-slate-200 px-1 py-px dark:border-slate-700">↵</kbd>
                  select
                </span>
                <span className="inline-flex items-center gap-1 text-[11px] text-slate-400 dark:text-slate-500">
                  <kbd className="rounded border border-slate-200 px-1 py-px dark:border-slate-700">esc</kbd>
                  close
                </span>
              </div>
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}
